/*
 * EVAText Web
 * Catálogo de comentarios para Microsoft Word.
 */

/* global document, Office, Word */

import { comentarios, ComentarioEVAText } from "./comentarios";

let textoBusqueda = "";
let grupoSeleccionado = "";

Office.onReady((info) => {
  if (info.host !== Office.HostType.Word) {
    return;
  }

  const mensajeCarga = document.getElementById("sideload-msg");
  const cuerpoAplicacion = document.getElementById("app-body");
  const buscador = document.getElementById("buscador") as HTMLInputElement | null;
  const filtroGrupo = document.getElementById("filtro-grupo") as HTMLSelectElement | null;

  if (mensajeCarga) {
    mensajeCarga.style.display = "none";
  }

  if (cuerpoAplicacion) {
    cuerpoAplicacion.style.display = "block";
  }

  llenarFiltroGrupos(filtroGrupo);
  actualizarResultados();

  buscador?.addEventListener("input", () => {
    textoBusqueda = normalizarTexto(buscador.value);
    actualizarResultados();
  });

  filtroGrupo?.addEventListener("change", () => {
    grupoSeleccionado = filtroGrupo.value;
    actualizarResultados();
  });
});

function llenarFiltroGrupos(filtro: HTMLSelectElement | null): void {
  if (!filtro) {
    return;
  }

  const grupos = Array.from(new Set(comentarios.map((comentario) => comentario.grupo)));

  grupos.forEach((grupo) => {
    const opcion = document.createElement("option");
    opcion.value = grupo;
    opcion.textContent = grupo;
    filtro.appendChild(opcion);
  });
}

function actualizarResultados(): void {
  const resultados = comentarios.filter((comentario) => {
    const coincideGrupo = !grupoSeleccionado || comentario.grupo === grupoSeleccionado;
    const contenido = normalizarTexto(
      `${comentario.grupo} ${comentario.categoria} ${comentario.nombre} ${comentario.texto}`
    );
    const coincideBusqueda = !textoBusqueda || contenido.includes(textoBusqueda);

    return coincideGrupo && coincideBusqueda;
  });

  mostrarComentarios(resultados);
  mostrarContador(resultados.length);
}

function mostrarContador(cantidad: number): void {
  const contador = document.getElementById("contador");

  if (!contador) {
    return;
  }

  contador.textContent = `${cantidad} de ${comentarios.length} comentarios`;
}

function mostrarComentarios(lista: ComentarioEVAText[]): void {
  const contenedor = document.getElementById("lista-comentarios");

  if (!contenedor) {
    return;
  }

  contenedor.replaceChildren();

  if (lista.length === 0) {
    const mensaje = document.createElement("p");
    mensaje.className = "sin-resultados";
    mensaje.textContent = "No se encontraron comentarios con esos criterios.";
    contenedor.appendChild(mensaje);
    return;
  }

  lista.forEach((comentario) => {
    const tarjeta = document.createElement("article");
    tarjeta.className = "tarjeta-comentario";

    const ruta = document.createElement("p");
    ruta.className = "categoria";
    ruta.textContent = `${comentario.grupo} · ${comentario.categoria}`;

    const encabezado = document.createElement("div");
    encabezado.className = "encabezado-tarjeta";

    const titulo = document.createElement("h2");
    titulo.textContent = comentario.nombre;
    encabezado.appendChild(titulo);

    if (comentario.requiereRevision) {
      const aviso = document.createElement("span");
      aviso.className = "aviso-revision";
      aviso.textContent = "Revisar texto";
      aviso.title = "Este comentario tenía un texto incompleto o posiblemente incorrecto en el proyecto anterior.";
      encabezado.appendChild(aviso);
    }

    const boton = document.createElement("button");
    boton.type = "button";
    boton.className = "boton-insertar";
    boton.textContent = "Insertar comentario";

    boton.addEventListener("click", () => {
      void insertarComentario(comentario);
    });

    tarjeta.append(ruta, encabezado, boton);
    contenedor.appendChild(tarjeta);
  });
}

async function insertarComentario(comentario: ComentarioEVAText): Promise<void> {
  mostrarEstado("Insertando comentario...", "informacion");

  try {
    await Word.run(async (context) => {
      const seleccion = context.document.getSelection();
      seleccion.load("text");

      await context.sync();

      if (!seleccion.text.trim()) {
        throw new Error(
          "Primero debes seleccionar una palabra, oración o fragmento en Word."
        );
      }

      seleccion.insertComment(comentario.texto);
      await context.sync();
    });

    mostrarEstado(`Se insertó el comentario: ${comentario.nombre}.`, "exito");
  } catch (error) {
    const mensaje = error instanceof Error ? error.message : String(error);

    mostrarEstado(mensaje, "error");
    console.error("Error de EVAText:", error);
  }
}

function mostrarEstado(
  mensaje: string,
  tipo: "informacion" | "exito" | "error"
): void {
  const estado = document.getElementById("estado");

  if (!estado) {
    return;
  }

  estado.textContent = mensaje;
  estado.className = `estado ${tipo}`;
}

function normalizarTexto(texto: string): string {
  return texto
    .toLocaleLowerCase("es")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}
